constraints:
1 <= N <= 10^{5}
1 <= Arr[i] <= 10^{5}

expected time complexity: O(N*LOG(N)).
expected auxiliary space: O(N).

standard_solution_code:
from bisect import bisect_left

def BinarySearch(a, x):
	i = bisect_left(a, x)
	if i:
		return i - 1
	else:
		return -1

def findMaximumBefore(arr, n):
	res = [-1] * (n + 1)
	lst = []
	lst.append(arr[0])
	for i in range(1, n):
		idx = BinarySearch(lst, arr[i])
		if idx != -1:
			res[i] = lst[idx]
		lst.insert(idx + 1, arr[i])
	return res

class Solution:

	def countArray(self, arr, n):
		small = findMaximumBefore(arr, n)
		large = [0] * n
		large[n - 1] = arr[n - 1]
		for i in range(n - 2, -1, -1):
			large[i] = max(large[i + 1], arr[i])
		res = -1
		ans = [-1]
		for i in range(1, n - 1):
			if small[i] != -1 and large[i + 1] > arr[i]:
				if res < small[i] * arr[i] * large[i + 1]:
					res = small[i] * arr[i] * large[i + 1]
					ans = [small[i], arr[i], large[i + 1]]
		return ans
